{"command": "create", "path": "/root/output/js/visualization.js", "security_risk": "MEDIUM", "summary": "Create D3 v6 visualization logic with linked interactions", "file_text": "(() => {
  const svg = d3.select('#bubble-chart');
  const tooltip = d3.select('#tooltip');
  const legendEl = d3.select('#legend');

  const width = +svg.attr('width');
  const height = +svg.attr('height');

  const sectorOrder = ['Information Technology', 'Industry', 'Energy', 'Financial', 'ETF'];

  const color = d3.scaleOrdinal()
    .domain(sectorOrder)
    .range(['#4e79a7', '#59a14f', '#e15759', '#f28e2b', '#b07aa1']);

  let selectedTicker = null;

  function formatMarketCap(value) {
    if (value == null || Number.isNaN(value)) return 'N/A';

    const abs = Math.abs(value);
    if (abs >= 1e12) return `${(value / 1e12).toFixed(2)}T`;
    if (abs >= 1e9) return `${(value / 1e9).toFixed(2)}B`;
    if (abs >= 1e6) return `${(value / 1e6).toFixed(2)}M`;
    return d3.format(',')(value);
  }

  function setSelected(ticker) {
    selectedTicker = selectedTicker === ticker ? null : ticker;
    renderSelection();
  }

  function renderSelection() {
    svg.selectAll('g.node')
      .classed('selected', d => d.ticker === selectedTicker)
      .classed('dimmed', d => selectedTicker && d.ticker !== selectedTicker);

    d3.select('#stock-table').selectAll('tbody tr')
      .classed('selected', d => d.ticker === selectedTicker);

    const row = d3.select('#stock-table').selectAll('tbody tr')
      .filter(d => d.ticker === selectedTicker)
      .node();

    if (row) row.scrollIntoView({ block: 'nearest' });
  }

  function showTooltip(event, d) {
    if (d.isEtf) return;

    tooltip
      .classed('visible', true)
      .html(`
        <div><strong>${d.ticker}</strong></div>
        <div>${d.fullName}</div>
        <div>Sector: ${d.sector}</div>
      `)
      .style('left', `${event.offsetX + 18}px`)
      .style('top', `${event.offsetY + 12}px`);
  }

  function hideTooltip() {
    tooltip.classed('visible', false);
  }

  function createLegend() {
    const items = legendEl.selectAll('div.legend-item')
      .data(sectorOrder)
      .enter()
      .append('div')
      .attr('class', 'legend-item');

    items.append('div')
      .attr('class', 'legend-swatch')
      .style('background', d => color(d));

    items.append('div')
      .text(d => d);
  }

  function sectorCenters() {
    const cx = width / 2;
    const cy = height / 2;

    const ring = 170;

    return {
      'Information Technology': { x: cx - ring, y: cy - ring * 0.8 },
      'Industry': { x: cx + ring, y: cy - ring * 0.8 },
      'Energy': { x: cx - ring, y: cy + ring * 0.9 },
      'Financial': { x: cx + ring, y: cy + ring * 0.9 },
      'ETF': { x: cx, y: cy }
    };
  }

  function computeRadiusScale(data) {
    const caps = data.filter(d => d.marketCap != null).map(d => d.marketCap);

    if (!caps.length) {
      return () => 22;
    }

    return d3.scaleSqrt()
      .domain([d3.min(caps), d3.max(caps)])
      .range([18, 60]);
  }

  function renderTable(data) {
    const tbody = d3.select('#stock-table tbody');

    const rows = tbody.selectAll('tr')
      .data(data, d => d.ticker)
      .join('tr')
      .on('click', (event, d) => {
        setSelected(d.ticker);
        event.stopPropagation();
      });

    rows.selectAll('td')
      .data(d => [d.ticker, d.fullName, d.sector, formatMarketCap(d.marketCap)])
      .join('td')
      .attr('class', (_, i) => (i === 3 ? 'num' : null))
      .text(d => d);
  }

  function renderBubbles(data) {
    const centers = sectorCenters();

    const nodeLayer = svg.append('g').attr('class', 'nodes');

    const node = nodeLayer.selectAll('g.node')
      .data(data, d => d.ticker)
      .join(enter => {
        const g = enter.append('g')
          .attr('class', 'node')
          .style('cursor', 'pointer')
          .on('mouseenter', (event, d) => showTooltip(event, d))
          .on('mousemove', (event, d) => showTooltip(event, d))
          .on('mouseleave', hideTooltip)
          .on('click', (event, d) => {
            setSelected(d.ticker);
            event.stopPropagation();
          });

        g.append('circle');
        g.append('text').style('pointer-events', 'none');
        return g;
      });

    node.select('circle')
      .attr('r', d => d.radius)
      .attr('fill', d => color(d.sector));

    node.select('text')
      .text(d => d.ticker);

    svg.on('click', () => {
      selectedTicker = null;
      renderSelection();
    });

    const simulation = d3.forceSimulation(data)
      .force('x', d3.forceX(d => centers[d.sector].x).strength(0.18))
      .force('y', d3.forceY(d => centers[d.sector].y).strength(0.18))
      .force('collide', d3.forceCollide(d => d.radius + 2.8).iterations(2))
      .force('charge', d3.forceManyBody().strength(-6))
      .stop();

    for (let i = 0; i < 280; i += 1) simulation.tick();

    node.attr('transform', d => `translate(${d.x},${d.y})`);
  }

  d3.csv('data/stock-descriptions.csv').then(raw => {
    const data = raw
      .map(d => {
        const sector = (d.sector || '').trim();
        const ticker = (d.ticker || '').trim();
        const fullName = (d['full name'] || '').trim();
        const marketCap = d.marketCap ? +d.marketCap : null;

        return {
          ticker,
          fullName,
          sector,
          marketCap: Number.isFinite(marketCap) ? marketCap : null,
          isEtf: sector === 'ETF'
        };
      })
      .sort((a, b) => d3.ascending(a.sector, b.sector) || d3.ascending(a.ticker, b.ticker));

    const r = computeRadiusScale(data);

    data.forEach(d => {
      d.radius = d.marketCap != null ? r(d.marketCap) : 22;
      d.x = width / 2;
      d.y = height / 2;
    });

    createLegend();
    renderTable(data);
    renderBubbles(data);
    renderSelection();
  });
})();
